import{_ as l,o as a,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2020-09-28","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2020-09-28","date":"2020-09-28T00:00:00.000Z","updated":"2020-09-29T00:00:00.000Z","tags":["Ceph","Pull Request","代码审核","测试流程","团队协作"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-09-28.md","filePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-09-28.md","lastUpdated":1780459816000}'),i={name:"posts/2020/Ceph_Orchestrator_Meeting_2020-09-28.md"};function o(n,e,s,h,u,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<p>Ceph Orchestrator Meeting 2020-09-28 的会议纪要如下：</p><h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间-2020-09-28" tabindex="-1">会议时间：2020-09-28 <a class="header-anchor" href="#会议时间-2020-09-28" aria-label="Permalink to &quot;会议时间：2020-09-28&quot;">​</a></h4><h4 id="参会人员-列出参会人员" tabindex="-1">参会人员：[列出参会人员] <a class="header-anchor" href="#参会人员-列出参会人员" aria-label="Permalink to &quot;参会人员：[列出参会人员]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>Pull Request 审核时间过长问题</strong></p><ul><li>讨论了两个具体的 PR，其中一个已开放28天，另一个21天。</li><li>提出是否使用“urgent”标签标记需要快速处理的 PR。</li></ul></li><li><p><strong>代码质量和紧急修复的平衡</strong></p><ul><li>强调在保证代码质量的同时，也需要考虑紧急修复的重要性。</li><li>对于对项目有重大影响的改进，可能需要更快合并，即使可能牺牲一些测试和文档。</li></ul></li><li><p><strong>团队成员的参与和责任</strong></p><ul><li>讨论了团队成员在 PR 审核和测试中的参与度，特别是 Red Hat 的成员需要更多地参与。</li><li>提出建立一个更开放的流程，让更多成员参与测试和审核，减轻主要负责人的负担。</li></ul></li><li><p><strong>测试和文档的改进</strong></p><ul><li>讨论了如何改进测试流程和文档，特别是在 Ceph 项目中如何更好地运行和分析测试。</li><li>提出可能需要一个上游工作坊来教育团队成员如何进行这些测试和分析。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ol><li><p><strong>标签使用</strong></p><ul><li>决定不使用“urgent”标签，而是通过日常站会来处理紧急的 PR。</li></ul></li><li><p><strong>团队参与</strong></p><ul><li>鼓励所有团队成员更多地参与到 PR 的审核和测试中，特别是 Red Hat 的成员。</li></ul></li><li><p><strong>测试和文档改进</strong></p><ul><li>计划创建一个详细的文档，指导团队成员如何运行和分析测试，并可能组织一个上游工作坊来进一步培训。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ol><li><p><strong>文档创建</strong></p><ul><li>由[具体负责人]负责创建一个详细的测试和 CI 流程文档，预计下周完成并在下次会议中展示。</li></ul></li><li><p><strong>团队培训</strong></p><ul><li>计划组织一个上游工作坊，教育团队成员如何进行测试和分析，特别是如何使用 Ceph Lab。</li></ul></li><li><p><strong>团队参与</strong></p><ul><li>所有团队成员应定期检查和参与 PR 的审核和测试，特别是 Red Hat 的成员。</li></ul></li></ol><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><ul><li>会议在感谢所有参会人员的参与和讨论后结束，并期待在下次会议中看到具体的进展和成果。</li></ul><h4 id="会议记录人-记录人姓名" tabindex="-1">会议记录人：[记录人姓名] <a class="header-anchor" href="#会议记录人-记录人姓名" aria-label="Permalink to &quot;会议记录人：[记录人姓名]&quot;">​</a></h4><h4 id="会议结束时间-具体时间" tabindex="-1">会议结束时间：[具体时间] <a class="header-anchor" href="#会议结束时间-具体时间" aria-label="Permalink to &quot;会议结束时间：[具体时间]&quot;">​</a></h4>',14)])])}const _=l(i,[["render",o]]);export{c as __pageData,_ as default};
